## Plan

**1. `src/api/account.ts`**: add `createUser` and `UserError` to the users import, add a `createSession` import, and add this route to the `accountRoutes` array:

```ts
import { createUser, getUser, publicUser, UserError } from "../auth/users.ts";
import { createSession, revokeSession } from "../auth/session.ts";
```

```ts
  {
    method: "POST",
    path: "/api/signup",
    handler: (req) => {
      const email = field(req.body, "email");
      const password = field(req.body, "password");
      if (!email || !password) return json(400, { error: "email and password are required" });
      try {
        const user = createUser(email, field(req.body, "name") ?? "", password);
        const session = createSession(user.id);
        return json(201, { token: session.token, user: publicUser(user) });
      } catch (err) {
        if (err instanceof UserError) return json(400, { error: err.message });
        throw err;
      }
    },
  },
```

Three choices to flag:
- **Starting the session:** I'll call `createSession(user.id)` and return `session.token`, which is exactly what `login()` does. I won't import `login` from `routes.ts`, because `routes.ts` already imports `account.ts` and that would create a circular import. Login also re-checks the password, which isn't needed here.
- **Missing email or password:** these return 400 with the same message login uses. Without this check, `createUser` would crash on `undefined.trim()` and the router would return a 500.
- **Missing name:** `name` is optional and defaults to `""`. In that case `createUser` already uses the email as the name.

**2. `test/signup.test.ts`** (new file):

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { createUser, resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates the user and returns a working session token", async () => {
  const res = await call("POST", "/api/signup", { email: "Grace@Example.com", name: "Grace", password: "hopper1906" });
  assert.equal(res.status, 201);
  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.deepEqual(user, { id: user.id, email: "grace@example.com", name: "Grace" });
  assert.equal("passwordHash" in user, false);
  const me = await call("GET", "/api/me", undefined, token);
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, user);
});

test("signed-up user can log in with the same password", async () => {
  await call("POST", "/api/signup", { email: "grace@example.com", name: "Grace", password: "hopper1906" });
  const res = await call("POST", "/api/login", { email: "grace@example.com", password: "hopper1906" });
  assert.equal(res.status, 200);
});

test("signup maps UserError to 400", async () => {
  createUser("ada@example.com", "Ada", "correct horse");
  const dup = await call("POST", "/api/signup", { email: "ADA@example.com", name: "Ada", password: "correct horse" });
  assert.deepEqual([dup.status, dup.body], [400, { error: "email already registered" }]);
  const short = await call("POST", "/api/signup", { email: "b@example.com", name: "B", password: "short" });
  assert.deepEqual([short.status, short.body], [400, { error: "password must be at least 8 characters" }]);
  const bad = await call("POST", "/api/signup", { email: "not-an-email", name: "C", password: "long enough" });
  assert.deepEqual([bad.status, bad.body], [400, { error: "invalid email" }]);
});

test("signup requires email and password", async () => {
  assert.equal((await call("POST", "/api/signup", { email: "d@example.com" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { password: "long enough" })).status, 400);
});
```

